import{_ as e,o as d,c as s,a2 as a}from"./chunks/framework.C_fNVUec.js";const k=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"docs/configuration.md","filePath":"docs/configuration.md","lastUpdated":1793898059000}'),o={name:"docs/configuration.md"};function i(n,t,c,r,h,l){return d(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Where ORC keeps its config and data, every config key and environment variable you are likely to set, logs, running as a background service, and authentication.</p><h2 id="files-and-directories" tabindex="-1">Files and directories <a class="header-anchor" href="#files-and-directories" aria-label="Permalink to &quot;Files and directories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Holds</th></tr></thead><tbody><tr><td><code>~/.orc/config.json</code></td><td>Global config. The CLI (<code>orc project use</code>), the dashboard and the desktop app write here.</td></tr><tr><td><code>./.orc/config.json</code></td><td>Optional config read from the directory the process starts in</td></tr><tr><td><code>~/.orc/orc.db</code></td><td>SQLite database (<code>db.path</code>)</td></tr><tr><td><code>~/.orc/knowledge/</code></td><td>Knowledge base files and index (beside the database)</td></tr><tr><td><code>~/.orc/secret.key</code></td><td>Key that encrypts stored secrets. Back it up with the database.</td></tr><tr><td><code>~/.orc/logs/orc.log</code></td><td>Structured log</td></tr><tr><td><code>~/.orc/daemon.log</code></td><td>Daemon stdout/stderr when run as a launchd or systemd service</td></tr><tr><td><code>~/.orc/daemon.pid</code></td><td>PID of the running daemon</td></tr><tr><td><code>~/.orc/desktop-daemon.log</code></td><td>Daemon output when the desktop app started it</td></tr><tr><td><code>~/.orc/bin/</code></td><td>CLI installed by the desktop app</td></tr></tbody></table><p><code>~</code> is <code>HOME</code> (<code>USERPROFILE</code> on Windows). Show the resolved paths and daemon state:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> home</span></span></code></pre></div><h2 id="precedence" tabindex="-1">Precedence <a class="header-anchor" href="#precedence" aria-label="Permalink to &quot;Precedence&quot;">​</a></h2><p>Later wins:</p><ol><li><code>~/.orc/config.json</code></li><li><code>./.orc/config.json</code></li><li>Environment variables</li><li>Global CLI flags (<code>--port</code>, <code>--host</code>, <code>--db</code>, <code>--secret</code>, <code>--log-level</code>, <code>--runner-timeout</code>, <code>--runner-max-jobs</code>, <code>--snapshot-max-bytes</code>)</li></ol><p>An invalid config file stops ORC with <code>Invalid orc config</code> and the failing key.</p><h2 id="example-config" tabindex="-1">Example config <a class="header-anchor" href="#example-config" aria-label="Permalink to &quot;Example config&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7700</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;host&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;secret&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;change-me&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;activeProject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_loop&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;default_backend&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;claude&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_workers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;runner&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;default_timeout_secs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_concurrent_jobs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="config-keys" tabindex="-1">Config keys <a class="header-anchor" href="#config-keys" aria-label="Permalink to &quot;Config keys&quot;">​</a></h2><h3 id="api" tabindex="-1"><code>api</code> <a class="header-anchor" href="#api" aria-label="Permalink to &quot;`api`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th><th>Purpose</th></tr></thead><tbody><tr><td><code>api.port</code></td><td><code>7700</code></td><td><code>ORC_API_PORT</code></td><td>API, dashboard and MCP port</td></tr><tr><td><code>api.host</code></td><td><code>127.0.0.1</code></td><td><code>ORC_API_HOST</code></td><td>Bind address. <code>0.0.0.0</code> exposes ORC on the network.</td></tr><tr><td><code>api.secret</code></td><td>none</td><td><code>ORC_API_SECRET</code></td><td>Bearer secret. Unset means no auth.</td></tr><tr><td><code>api.session_days</code></td><td><code>30</code></td><td><code>ORC_API_SESSION_DAYS</code></td><td>Dashboard sign-in and default token lifetime (1-365)</td></tr><tr><td><code>api.cors_origins</code></td><td><code>[]</code></td><td><code>ORC_API_CORS_ORIGINS</code> (comma-separated)</td><td>Extra browser origins allowed to call the API</td></tr></tbody></table><h3 id="db-activeproject" tabindex="-1"><code>db</code>, <code>activeProject</code> <a class="header-anchor" href="#db-activeproject" aria-label="Permalink to &quot;`db`, `activeProject`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th><th>Purpose</th></tr></thead><tbody><tr><td><code>db.path</code></td><td><code>~/.orc/orc.db</code></td><td><code>ORC_DB_PATH</code></td><td>SQLite file</td></tr><tr><td><code>activeProject</code></td><td>none</td><td><code>ORC_ACTIVE_PROJECT</code></td><td>Default project for CLI and MCP calls</td></tr></tbody></table><h3 id="agent-loop" tabindex="-1"><code>agent_loop</code> <a class="header-anchor" href="#agent-loop" aria-label="Permalink to &quot;`agent_loop`&quot;">​</a></h3><p>The task loop picks up <code>todo</code> and <code>changes_requested</code> tasks and runs agents on them.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th></tr></thead><tbody><tr><td><code>agent_loop.enabled</code></td><td><code>false</code></td><td><code>ORC_AGENT_LOOP_ENABLED</code></td></tr><tr><td><code>agent_loop.poll_interval_minutes</code></td><td><code>5</code></td><td><code>ORC_AGENT_LOOP_POLL_INTERVAL</code></td></tr><tr><td><code>agent_loop.max_workers</code></td><td><code>1</code></td><td><code>ORC_AGENT_LOOP_MAX_WORKERS</code></td></tr><tr><td><code>agent_loop.default_backend</code></td><td><code>claude</code></td><td><code>ORC_AGENT_LOOP_DEFAULT_BACKEND</code></td></tr><tr><td><code>agent_loop.session_idle_timeout_minutes</code></td><td><code>20</code></td><td><code>ORC_AGENT_LOOP_IDLE_TIMEOUT</code></td></tr><tr><td><code>agent_loop.session_max_lifetime_minutes</code></td><td><code>120</code></td><td><code>ORC_AGENT_LOOP_MAX_LIFETIME</code></td></tr><tr><td><code>agent_loop.worker_auto_approve</code></td><td><code>true</code></td><td><code>ORC_AGENT_LOOP_AUTO_APPROVE</code></td></tr><tr><td><code>agent_loop.default_flow</code></td><td><code>orc-default</code></td><td><code>ORC_AGENT_LOOP_DEFAULT_FLOW</code></td></tr><tr><td><code>agent_loop.review_flow</code></td><td><code>orc-review-only</code></td><td><code>ORC_AGENT_LOOP_REVIEW_FLOW</code></td></tr><tr><td><code>agent_loop.max_node_retries</code></td><td><code>2</code></td><td><code>ORC_AGENT_LOOP_MAX_NODE_RETRIES</code></td></tr><tr><td><code>agent_loop.max_flow_runs_per_task</code></td><td><code>6</code></td><td><code>ORC_AGENT_LOOP_MAX_FLOW_RUNS</code></td></tr></tbody></table><p>Run <code>orc doctor</code> to see which backends are usable. See <a href="./task-flows">Task flows</a>.</p><h3 id="runner-jobs" tabindex="-1"><code>runner</code> (jobs) <a class="header-anchor" href="#runner-jobs" aria-label="Permalink to &quot;`runner` (jobs)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th></tr></thead><tbody><tr><td><code>runner.default_timeout_secs</code></td><td><code>300</code></td><td><code>ORC_RUNNER_TIMEOUT</code></td></tr><tr><td><code>runner.max_concurrent_jobs</code></td><td><code>5</code></td><td><code>ORC_RUNNER_MAX_JOBS</code></td></tr><tr><td><code>runner.log_retention_days</code></td><td><code>30</code></td><td><code>ORC_RUNNER_LOG_DAYS</code></td></tr></tbody></table><h3 id="context-memory" tabindex="-1"><code>context</code>, <code>memory</code> <a class="header-anchor" href="#context-memory" aria-label="Permalink to &quot;`context`, `memory`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th><th>Purpose</th></tr></thead><tbody><tr><td><code>context.snapshot_max_bytes</code></td><td><code>2048</code></td><td><code>ORC_SNAPSHOT_MAX_BYTES</code></td><td>Session snapshot budget</td></tr><tr><td><code>context.layer1_task_limit</code></td><td><code>10</code></td><td><code>ORC_LAYER1_TASKS</code></td><td>Tasks in the <code>context</code> result</td></tr><tr><td><code>context.layer1_memory_limit</code></td><td><code>30</code></td><td><code>ORC_LAYER1_MEMORIES</code></td><td>Memories in the <code>context</code> result</td></tr><tr><td><code>memory.max_content_chars</code></td><td><code>800</code></td><td>none</td><td>Longest memory content</td></tr></tbody></table><h3 id="knowledge" tabindex="-1"><code>knowledge</code> <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;`knowledge`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th></tr></thead><tbody><tr><td><code>knowledge.root</code></td><td>beside <code>db.path</code></td><td><code>ORC_KNOWLEDGE_ROOT</code></td></tr><tr><td><code>knowledge.parser</code></td><td><code>auto</code></td><td><code>ORC_KNOWLEDGE_PARSER</code></td></tr><tr><td><code>knowledge.embedding.provider</code></td><td><code>none</code> (<code>none</code>, <code>ollama</code>, <code>openai</code>)</td><td><code>ORC_KNOWLEDGE_EMBEDDING_PROVIDER</code></td></tr><tr><td><code>knowledge.embedding.base_url</code></td><td>provider default</td><td><code>ORC_KNOWLEDGE_EMBEDDING_URL</code></td></tr><tr><td><code>knowledge.embedding.model</code></td><td>provider default</td><td><code>ORC_KNOWLEDGE_EMBEDDING_MODEL</code></td></tr><tr><td><code>knowledge.embedding.api_key</code></td><td>none</td><td><code>ORC_KNOWLEDGE_EMBEDDING_API_KEY</code></td></tr><tr><td><code>knowledge.max_upload_bytes</code></td><td><code>104857600</code> (100 MB)</td><td>none</td></tr></tbody></table><p>Most knowledge settings are also editable under <strong>Settings → Knowledge</strong>.</p><h3 id="terminals-ssh" tabindex="-1"><code>terminals</code>, <code>ssh</code> <a class="header-anchor" href="#terminals-ssh" aria-label="Permalink to &quot;`terminals`, `ssh`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th><th>Purpose</th></tr></thead><tbody><tr><td><code>terminals.enabled</code></td><td><code>true</code></td><td><code>ORC_TERMINALS_ENABLED</code></td><td>Browser terminals</td></tr><tr><td><code>terminals.max</code></td><td><code>8</code></td><td>none</td><td>Concurrent terminals (1-64)</td></tr><tr><td><code>terminals.shell</code></td><td>unset</td><td><code>ORC_TERMINALS_SHELL</code></td><td>Shell to launch</td></tr><tr><td><code>ssh.host</code></td><td>none</td><td><code>ORC_SSH_HOST</code></td><td><code>~/.ssh/config</code> host alias to run agents, terminals and git on</td></tr><tr><td><code>ssh.remote_port</code></td><td>none</td><td><code>ORC_SSH_REMOTE_PORT</code></td><td>Port the reverse tunnel opens on the SSH host so agents there reach ORC</td></tr></tbody></table><p>Pick the execution host from <strong>Settings → Execution host</strong>. Switching applies to new actions. When <code>ORC_SSH_HOST</code> is set, the selection is fixed.</p><h3 id="rules-mcp-github" tabindex="-1"><code>rules</code>, <code>mcp</code>, <code>github</code> <a class="header-anchor" href="#rules-mcp-github" aria-label="Permalink to &quot;`rules`, `mcp`, `github`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env</th><th>Purpose</th></tr></thead><tbody><tr><td><code>rules.enabled</code></td><td><code>false</code></td><td><code>ORC_RULES_ENABLED</code></td><td>Enforce <a href="./agent-rules">agent rules</a></td></tr><tr><td><code>mcp.default_mode</code></td><td><code>meta</code></td><td>none</td><td>MCP tool surface: <code>meta</code> or <code>full</code></td></tr><tr><td><code>github.token</code></td><td>none</td><td><code>ORC_GITHUB_TOKEN</code></td><td>Token for ORC&#39;s GitHub calls (pull requests, reviews)</td></tr></tbody></table><h3 id="gateway-telegram-slack" tabindex="-1"><code>gateway</code> (Telegram, Slack) <a class="header-anchor" href="#gateway-telegram-slack" aria-label="Permalink to &quot;`gateway` (Telegram, Slack)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Env</th><th>Effect</th></tr></thead><tbody><tr><td><code>ORC_TELEGRAM_TOKEN</code></td><td>Enables the Telegram gateway with this bot token</td></tr><tr><td><code>ORC_SLACK_BOT_TOKEN</code>, <code>ORC_SLACK_APP_TOKEN</code></td><td>Enables the Slack gateway (Socket Mode)</td></tr></tbody></table><p>Channels are configured under <strong>Settings → Channels</strong>.</p><h3 id="speech-tts" tabindex="-1"><code>speech</code>, <code>tts</code> <a class="header-anchor" href="#speech-tts" aria-label="Permalink to &quot;`speech`, `tts`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Env</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ORC_SPEECH_PROVIDER</code></td><td><code>openai</code>, <code>groq</code> or <code>qwen</code></td></tr><tr><td><code>ORC_SPEECH_LANGUAGE</code></td><td>Transcription language</td></tr><tr><td><code>ORC_TTS_PROVIDER</code></td><td><code>openai</code> or <code>qwen</code></td></tr><tr><td><code>ORC_TTS_VOICE</code></td><td>Voice (default <code>alloy</code>)</td></tr><tr><td><code>ORC_TTS_MODE</code></td><td><code>voice_only</code> or <code>always</code></td></tr><tr><td><code>ORC_OPENAI_API_KEY</code>, <code>ORC_GROQ_API_KEY</code>, <code>ORC_QWEN_API_KEY</code></td><td>Speech provider keys</td></tr></tbody></table><p>Setting any <code>ORC_SPEECH_*</code> or provider key enables speech; setting any <code>ORC_TTS_*</code> enables text-to-speech.</p><h2 id="other-environment-variables" tabindex="-1">Other environment variables <a class="header-anchor" href="#other-environment-variables" aria-label="Permalink to &quot;Other environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ORC_HOME</code></td><td><code>~/.orc</code></td><td>Location of <code>daemon.pid</code> and <code>daemon.log</code> only. Config and database stay under <code>~/.orc</code>.</td></tr><tr><td><code>ORC_API_BASE</code></td><td>from <code>api.host</code>/<code>api.port</code></td><td>ORC origin for the CLI, stdio MCP and hooks</td></tr><tr><td><code>ORC_SESSION_ID</code></td><td>none</td><td>Session attribution for MCP and CLI writes</td></tr><tr><td><code>ORC_LOG_LEVEL</code></td><td><code>info</code></td><td><code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code></td></tr><tr><td><code>ORC_LOG_DIR</code></td><td><code>~/.orc</code></td><td>Parent of the <code>logs/</code> directory</td></tr><tr><td><code>ORC_LOG_FILE</code></td><td>on</td><td><code>0</code> disables the log file</td></tr><tr><td><code>ORC_WEB_DIST</code></td><td>bundled</td><td>Serve a different dashboard build</td></tr><tr><td><code>ORC_SQLITE_VEC_PATH</code></td><td>bundled</td><td>sqlite-vec library for vector search</td></tr><tr><td><code>AGENTAPI_URL</code></td><td><code>http://localhost:3284</code></td><td>agentapi server for the <code>agentapi</code> backend</td></tr><tr><td><code>ANTHROPIC_API_KEY</code></td><td>none</td><td><code>claude</code> backend</td></tr></tbody></table><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Serves</th></tr></thead><tbody><tr><td><code>7700</code></td><td>REST API (<code>/api/*</code>), dashboard (<code>/</code>), MCP (<code>/mcp</code>), OpenAPI (<code>/openapi.json</code>), Swagger UI (<code>/docs</code>)</td></tr></tbody></table><p>Change it with <code>api.port</code>, <code>ORC_API_PORT</code> or <code>orc --port &lt;n&gt; daemon start</code>. The desktop app reads the same setting.</p><p>Health check (no auth needed):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:7700/api/health</span></span></code></pre></div><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p><code>~/.orc/logs/orc.log</code> holds JSON lines. It rotates at 10 MB and keeps three rotated files (<code>orc.log.1</code> to <code>orc.log.3</code>). The terminal gets the same entries in readable form on stderr.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;level&quot;:&quot;error&quot;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.orc/logs/orc.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.orc/logs/orc.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h2 id="run-as-a-background-service" tabindex="-1">Run as a background service <a class="header-anchor" href="#run-as-a-background-service" aria-label="Permalink to &quot;Run as a background service&quot;">​</a></h2><p><code>orc daemon start</code> runs in the foreground. To start it at login and keep it running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # register and start now</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # remove the registration</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Platform</th><th>Mechanism</th><th>Restarts on crash</th></tr></thead><tbody><tr><td>macOS</td><td>launchd agent <code>~/Library/LaunchAgents/com.orc.daemon.plist</code></td><td>Yes</td></tr><tr><td>Linux</td><td>systemd user service <code>~/.config/systemd/user/orc-daemon.service</code></td><td>Yes (on failure)</td></tr><tr><td>Windows</td><td>Registry Run key <code>HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run\\OrcDaemon</code></td><td>No</td></tr></tbody></table><p>No admin rights needed. Service output goes to <code>~/.orc/daemon.log</code> on macOS and Linux.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # stop the running daemon</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # list scheduled jobs and their last runs</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                            # API health and counts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # macOS</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orc-daemon</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Linux</span></span></code></pre></div><p><code>orc daemon install</code> refuses an <code>orc</code> that lives under nvm, fnm, volta, asdf or nodenv paths. Install a <a href="./install#pre-built-binary">pre-built binary</a>, or pass <code>--force</code>.</p><p><code>orc daemon start</code> merges your login shell&#39;s <code>PATH</code> on macOS and Linux, so agent CLIs such as <code>claude</code>, <code>codex</code> and <code>cursor-agent</code> are found when the daemon runs as a service.</p><p>If a daemon already answers on the port, the desktop app uses it instead of starting its own.</p><p><code>orc api</code> starts only the API server, without the scheduler, watchers, gateway or task loop.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>With no secret, ORC accepts every request. Keep <code>api.host</code> on <code>127.0.0.1</code> in that case.</p><p>Set a secret:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # one run</span></span></code></pre></div><p>or put it in <code>~/.orc/config.json</code> as <code>api.secret</code>, or set <code>ORC_API_SECRET</code>. The desktop app generates and saves one for you.</p><table tabindex="0"><thead><tr><th>Client</th><th>How it authenticates</th></tr></thead><tbody><tr><td>CLI, stdio MCP on the same machine</td><td>Reads the secret from config or <code>ORC_API_SECRET</code></td></tr><tr><td>HTTP clients, HTTP MCP</td><td><code>Authorization: Bearer &lt;secret or access token&gt;</code></td></tr><tr><td>Dashboard</td><td>Asks for the secret once and stores a signed HttpOnly cookie for <code>api.session_days</code></td></tr><tr><td>Desktop app</td><td>Sends the secret it configured</td></tr></tbody></table><p>Unauthenticated paths: <code>/health</code>, <code>/api/health</code>, <code>/api/auth/session</code>, <code>/api/auth/token</code>. Handoff upload, session-sync, skill download and scratchpad content URLs skip the secret but check their own signed, expiring link.</p><h3 id="access-tokens" tabindex="-1">Access tokens <a class="header-anchor" href="#access-tokens" aria-label="Permalink to &quot;Access tokens&quot;">​</a></h3><p>An access token is a signed bearer credential that expires. Use one instead of the raw secret for agents and scripts.</p><p>Create one under <strong>Settings → Security</strong>, or:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:7700/api/auth/token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;secret&quot;:&quot;&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORC_API_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;&quot;}&#39;</span></span></code></pre></div><p>Returns <code>{&quot;token&quot;: &quot;...&quot;, &quot;expires_at&quot;: &lt;unix seconds&gt;}</code>. Pass <code>expires_at</code> (unix seconds) to choose the expiry, up to 365 days. Rotating the secret revokes every token.</p><p>For exposing ORC beyond localhost, see <a href="./self-hosted">Self-hosting</a>.</p>',72)])])}const g=e(o,[["render",i]]);export{k as __pageData,g as default};
